import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import { PersistenceService } from '../src/services/persistence-service';
import { DocumentService } from '../src/services/document-service';
import { IndexingService } from '../src/services/indexing-service';
import { QaService } from '../src/services/qa-service';

/** A full set of services over one data directory, like the main process builds at startup. */
export interface TestApp {
  dir: string;
  persistence: PersistenceService;
  documents: DocumentService;
  indexing: IndexingService;
  qa: QaService;
}

export function createTestDir(): string {
  return fs.mkdtempSync(path.join(os.tmpdir(), 'kb-test-'));
}

export function createApp(dir: string): TestApp {
  const persistence = new PersistenceService(dir);
  const indexing = new IndexingService(persistence);
  return {
    dir,
    persistence,
    documents: new DocumentService(persistence),
    indexing,
    qa: new QaService(persistence, indexing),
  };
}

export function removeTestDir(dir: string): void {
  fs.rmSync(dir, { recursive: true, force: true });
}
