import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { createApp, createTestDir, removeTestDir, TestApp } from './helpers';

describe('answer feedback', () => {
  let dir: string;
  let app: TestApp;

  beforeEach(() => {
    dir = createTestDir();
    app = createApp(dir);
  });

  afterEach(() => {
    removeTestDir(dir);
  });

  it('gives every answer a unique non-empty string id', async () => {
    const first = await app.qa.ask('What is the architecture?');
    const second = await app.qa.ask('What is the architecture?');
    expect(typeof first.id).toBe('string');
    expect(first.id.length).toBeGreaterThan(0);
    expect(second.id).not.toBe(first.id);
  });

  it('stores an up or down rating and lists it as {answerId, rating, timestamp}', async () => {
    const answer = await app.qa.ask('How does import work?');
    const before = Date.now();
    const entry = app.qa.submitFeedback(answer.id, 'up');

    expect(entry.answerId).toBe(answer.id);
    expect(entry.rating).toBe('up');
    expect(Date.parse(entry.timestamp)).toBeGreaterThanOrEqual(before - 1000);

    const list = app.qa.getFeedback();
    expect(list).toEqual([{ answerId: answer.id, rating: 'up', timestamp: entry.timestamp }]);
  });

  it('keeps one rating per answer: a second submit replaces the first', async () => {
    const answer = await app.qa.ask('How does indexing work?');
    app.qa.submitFeedback(answer.id, 'up');
    app.qa.submitFeedback(answer.id, 'down');

    const list = app.qa.getFeedback();
    expect(list).toHaveLength(1);
    expect(list[0].rating).toBe('down');
  });

  it('records ratings for several answers independently', async () => {
    const a = await app.qa.ask('first question');
    const b = await app.qa.ask('second question');
    app.qa.submitFeedback(a.id, 'up');
    app.qa.submitFeedback(b.id, 'down');

    const byId = Object.fromEntries(app.qa.getFeedback().map(e => [e.answerId, e.rating]));
    expect(byId).toEqual({ [a.id]: 'up', [b.id]: 'down' });
  });

  it('rejects a rating that is not up or down', async () => {
    const answer = await app.qa.ask('any question');
    expect(() => app.qa.submitFeedback(answer.id, 'sideways' as 'up')).toThrow(/Invalid rating/);
    expect(app.qa.getFeedback()).toEqual([]);
  });

  it('rejects feedback for an answer that does not exist', async () => {
    expect(() => app.qa.submitFeedback('no-such-answer', 'up')).toThrow(/Unknown answer/);
    expect(app.qa.getFeedback()).toEqual([]);
  });

  it('persists ratings across a restart (a new service instance on the same directory)', async () => {
    const answer = await app.qa.ask('persistence question');
    app.qa.submitFeedback(answer.id, 'up');

    const restarted = createApp(dir);
    expect(restarted.qa.getFeedback()).toEqual(app.qa.getFeedback());
    expect(restarted.qa.getFeedback()[0]).toMatchObject({ answerId: answer.id, rating: 'up' });
  });

  it('gives answers saved before ids existed an id, so they can be rated', async () => {
    app.persistence.writeJson('qa-history.json', [
      {
        question: 'old question',
        response: { answer: 'old answer', citations: [], confidence: 0.3, timestamp: new Date().toISOString() },
      },
    ]);

    const [legacy] = app.qa.getHistory();
    expect(typeof legacy.response.id).toBe('string');
    expect(legacy.response.id.length).toBeGreaterThan(0);

    const entry = app.qa.submitFeedback(legacy.response.id, 'down');
    expect(entry.answerId).toBe(legacy.response.id);
    // The id is stored, so it stays the same on the next read.
    expect(createApp(dir).qa.getHistory()[0].response.id).toBe(legacy.response.id);
  });
});
