cat > scripts/e2e-app.mjs <<'EOF'
// End-to-end checks against the real Electron app, driven over Chrome DevTools.
// Each scenario launches the app on a given user-data directory, runs its steps in the
// page, and closes the app. Reusing one directory across two launches tests persistence.
//
// Usage:
//   node --experimental-websocket scripts/e2e-app.mjs <scenario> <userDataDir> [port]
// Scenarios: feedback-ask, feedback-check
import { spawn } from 'child_process';
import path from 'path';
import { fileURLToPath } from 'url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const [scenario, userData, portArg] = process.argv.slice(2);
const port = portArg || '9361';
if (!scenario || !userData) {
  console.error('usage: e2e-app.mjs <scenario> <userDataDir> [port]');
  process.exit(2);
}

const env = { ...process.env };
delete env.NODE_OPTIONS;
const electron = spawn('npx', ['electron', '.', `--remote-debugging-port=${port}`, `--user-data-dir=${userData}`], {
  cwd: root,
  env,
  stdio: 'ignore',
});

async function connect() {
  for (let i = 0; i < 60; i++) {
    try {
      const targets = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json();
      const page = targets.find(t => t.type === 'page');
      if (page) {
        const ws = new WebSocket(page.webSocketDebuggerUrl);
        await new Promise((resolve, reject) => {
          ws.addEventListener('open', resolve);
          ws.addEventListener('error', reject);
        });
        return ws;
      }
    } catch {
      // not up yet
    }
    await new Promise(r => setTimeout(r, 500));
  }
  throw new Error('Electron did not expose a page on the DevTools port');
}

const ws = await connect();
let nextId = 1;
const pending = new Map();
ws.addEventListener('message', ev => {
  const msg = JSON.parse(ev.data);
  const resolve = pending.get(msg.id);
  if (!resolve) return;
  pending.delete(msg.id);
  resolve(msg);
});

/** Evaluate an async expression in the page and return its JSON value. */
async function run(expression) {
  const id = nextId++;
  const reply = await new Promise(resolve => {
    pending.set(id, resolve);
    ws.send(JSON.stringify({
      id,
      method: 'Runtime.evaluate',
      params: { expression, awaitPromise: true, returnByValue: true },
    }));
  });
  if (reply.result?.exceptionDetails) {
    throw new Error(`page error: ${JSON.stringify(reply.result.exceptionDetails.exception?.description ?? reply.result.exceptionDetails.text)}`);
  }
  return reply.result?.result?.value;
}

const sleep = ms => new Promise(r => setTimeout(r, ms));
const results = {};
const check = (name, ok, detail) => {
  results[name] = { ok: Boolean(ok), ...(detail !== undefined ? { detail } : {}) };
};

// Wait until the window's bridge and the first render are ready.
for (let i = 0; i < 40; i++) {
  if (await run("typeof window.knowledgeBase === 'object' && !!document.querySelector('form')")) break;
  await sleep(250);
}

try {
  if (scenario === 'feedback-ask') {
    // Ask through the UI, then check both feedback buttons render for that answer.
    await run(`(async () => {
      const input = document.querySelector('form input[type=text]');
      const setValue = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set;
      setValue.call(input, 'What is the architecture of the system?');
      input.dispatchEvent(new Event('input', { bubbles: true }));
      document.querySelector('form').requestSubmit();
      for (let i = 0; i < 60 && !document.querySelector('[aria-label="Mark answer helpful"]'); i++) {
        await new Promise(r => setTimeout(r, 100));
      }
      return true;
    })()`);
    const buttons = await run(`({
      helpful: document.querySelectorAll('[aria-label="Mark answer helpful"]').length,
      notHelpful: document.querySelectorAll('[aria-label="Mark answer not helpful"]').length,
    })`);
    check('ui-buttons-render', buttons.helpful >= 1 && buttons.notHelpful >= 1, buttons);

    // Click "helpful" in the UI and confirm the rating reached the main process.
    await run(`document.querySelector('[aria-label="Mark answer helpful"]').click(); new Promise(r => setTimeout(r, 300))`);
    const pressed = await run(`document.querySelector('[aria-label="Mark answer helpful"]').getAttribute('aria-pressed')`);
    check('ui-click-marks-pressed', pressed === 'true', { pressed });

    // Rate a second answer through the bridge, which is what a script would do.
    const second = await run(`(async () => {
      const answer = await window.knowledgeBase.qa.ask('How does retrieval work?');
      const entry = await window.knowledgeBase.feedback.submit(answer.id, 'down');
      return { answerId: answer.id, entry };
    })()`);
    check('bridge-submit-returns-entry', second.entry.answerId === second.answerId && second.entry.rating === 'down', second);

    const list = await run(`window.knowledgeBase.feedback.list()`);
    results.listAfterAsk = list;
    check('list-has-two-entries', list.length === 2, { count: list.length });
  } else if (scenario === 'feedback-check') {
    const list = await run(`window.knowledgeBase.feedback.list()`);
    results.listAfterRestart = list;
    check('feedback-survives-restart', list.length === 2 && list.every(e => typeof e.answerId === 'string' && ['up', 'down'].includes(e.rating) && typeof e.timestamp === 'string'), { count: list.length });

    // The UI shows the stored rating as pressed for the answers that were rated.
    await run(`(async () => {
      const answers = await window.knowledgeBase.qa.history();
      return answers.length;
    })()`);
    const history = await run(`window.knowledgeBase.qa.history()`);
    const ratedIds = new Set(list.map(e => e.answerId));
    const historyIds = history.map(h => h.response.id);
    check('history-ids-match-feedback', historyIds.every(id => typeof id === 'string' && id.length > 0) && list.every(e => historyIds.includes(e.answerId)));
    const clicked = await run(`(async () => {
      document.querySelector('button')
        && [...document.querySelectorAll('button')].find(b => b.textContent === 'Show History')?.click();
      await new Promise(r => setTimeout(r, 400));
      const pressedDown = [...document.querySelectorAll('[aria-label="Mark answer not helpful"][aria-pressed="true"]')].length;
      const pressedUp = [...document.querySelectorAll('[aria-label="Mark answer helpful"][aria-pressed="true"]')].length;
      return { pressedUp, pressedDown, historyButtons: document.querySelectorAll('[aria-label="Mark answer helpful"]').length };
    })()`);
    results.historyView = clicked;
    check('history-view-shows-buttons-with-ratings', clicked.historyButtons === history.length && clicked.pressedUp + clicked.pressedDown === ratedIds.size, clicked);
  } else {
    throw new Error(`unknown scenario ${scenario}`);
  }
} catch (err) {
  check('scenario-error', false, String(err));
}

console.log(JSON.stringify(results, null, 2));
const failed = Object.entries(results).filter(([k, v]) => k.includes('-') && v && v.ok === false);
ws.close();
electron.kill();
await sleep(500);
const pass = failed.length === 0 && results['scenario-error'] === undefined;
console.log(pass ? 'E2E PASS' : `E2E FAIL: ${failed.map(([k]) => k).join(', ')}`);
process.exit(pass ? 0 : 1);
EOF
