import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { createApp, createTestDir, removeTestDir, TestApp } from './helpers';

describe('reset all data', () => {
  let dir: string;
  let importDir: string;
  let app: TestApp;

  beforeEach(() => {
    dir = createTestDir();
    importDir = fs.mkdtempSync(path.join(os.tmpdir(), 'kb-src-'));
    app = createApp(dir);
  });

  afterEach(() => {
    removeTestDir(dir);
    removeTestDir(importDir);
  });

  /** Fill every store: documents, indexed chunks, Q&A history and feedback. */
  async function populate() {
    const file = path.join(importDir, 'notes.md');
    fs.writeFileSync(file, 'The architecture has three layers.\n\nIndexing splits documents into chunks.');
    const doc = app.documents.importDocument(file);
    app.indexing.startIndexing(doc.id);
    await app.indexing.startIndexing();
    const answer = await app.qa.ask('What is the architecture?');
    app.qa.submitFeedback(answer.id, 'up');
    return { doc, answer };
  }

  it('starts from a populated state so the reset has something to clear', async () => {
    const { doc } = await populate();
    expect(app.documents.listDocuments()).toHaveLength(1);
    expect(app.indexing.getChunksForDocument(doc.id).length).toBeGreaterThan(0);
    expect(app.qa.getHistory()).toHaveLength(1);
    expect(app.qa.getFeedback()).toHaveLength(1);
  });

  it('clears documents, chunks, Q&A history and feedback', async () => {
    const { doc } = await populate();
    const docFile = path.join(app.persistence.getDocumentsDir(), 'notes.md');
    expect(fs.existsSync(docFile)).toBe(true);

    app.persistence.resetAll();

    expect(app.documents.listDocuments()).toEqual([]);
    expect(app.documents.getDocument(doc.id)).toBeNull();
    expect(app.indexing.getChunksForDocument(doc.id)).toEqual([]);
    expect(app.indexing.getAllChunks()).toEqual([]);
    expect(app.qa.getHistory()).toEqual([]);
    expect(app.qa.getFeedback()).toEqual([]);
    expect(fs.existsSync(docFile)).toBe(false);
    expect(app.indexing.getStatus()).toMatchObject({ status: 'idle', currentIndexed: 0, totalDocuments: 0 });
  });

  it('leaves the app usable and empty after a restart', async () => {
    await populate();
    app.persistence.resetAll();

    const restarted = createApp(dir);
    expect(restarted.documents.listDocuments()).toEqual([]);
    expect(restarted.qa.getHistory()).toEqual([]);
    expect(restarted.qa.getFeedback()).toEqual([]);
    expect(restarted.indexing.getAllChunks()).toEqual([]);

    // New data works after the reset.
    const answer = await restarted.qa.ask('anything');
    expect(restarted.qa.getHistory()).toHaveLength(1);
    expect(restarted.qa.getHistory()[0].response.id).toBe(answer.id);
  });
});
EOF
