import { useEffect, useRef } from 'react';
import { QAHistory, FeedbackRating, Citation } from '../../shared/types';
import { describeConfidence } from '../../shared/confidence';
import { AnswerFeedback } from './AnswerFeedback';

interface Props {
  history: QAHistory[];
  /** Question that has been sent but not answered yet. */
  pendingQuestion: string | null;
  feedback: Record<string, FeedbackRating>;
  onRate: (answerId: string, rating: FeedbackRating) => void;
  onClear: () => void;
}

/** The Q&A history as a conversation: each question on the right, each answer on the left. */
export function ConversationHistory({ history, pendingQuestion, feedback, onRate, onClear }: Props) {
  const endRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    endRef.current?.scrollIntoView({ block: 'end' });
  }, [history.length, pendingQuestion]);

  if (history.length === 0 && !pendingQuestion) {
    return (
      <div style={{ color: '#666', textAlign: 'center', paddingTop: '40px' }}>
        No conversation history yet. Ask a question to get started.
      </div>
    );
  }

  return (
    <div>
      <div style={{
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center',
        marginBottom: '16px',
      }}>
        <h3 style={{ fontSize: '16px', fontWeight: 600 }}>Conversation</h3>
        {history.length > 0 && (
          <button
            onClick={onClear}
            style={{
              padding: '4px 10px',
              background: '#d9534f',
              color: '#fff',
              border: 'none',
              borderRadius: '3px',
              cursor: 'pointer',
              fontSize: '12px',
            }}
          >
            Clear History
          </button>
        )}
      </div>

      {history.map((item, index) => (
        <div key={item.response.id ?? index} style={{ marginBottom: '18px' }}>
          <QuestionBubble question={item.question} timestamp={item.response.timestamp} />
          <AnswerBubble
            answerId={item.response.id}
            answer={item.response.answer}
            citations={item.response.citations}
            confidence={item.response.confidence}
            timestamp={item.response.timestamp}
            rating={item.response.id ? feedback[item.response.id] : undefined}
            onRate={onRate}
          />
        </div>
      ))}

      {pendingQuestion && (
        <div style={{ marginBottom: '18px' }}>
          <QuestionBubble question={pendingQuestion} />
          <div style={{ fontSize: '12px', color: '#888', paddingLeft: '4px' }}>Thinking...</div>
        </div>
      )}
      <div ref={endRef} />
    </div>
  );
}

function QuestionBubble({ question, timestamp }: { question: string; timestamp?: string }) {
  return (
    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-end', marginBottom: '8px' }}>
      <div style={{
        maxWidth: '80%',
        padding: '10px 14px',
        background: '#533483',
        color: '#fff',
        borderRadius: '12px 12px 2px 12px',
        fontSize: '14px',
        lineHeight: 1.5,
        overflowWrap: 'anywhere',
      }}>
        {question}
      </div>
      {timestamp && <div style={{ fontSize: '10px', color: '#666', marginTop: '3px' }}>{formatTime(timestamp)}</div>}
    </div>
  );
}

interface AnswerProps {
  answerId: string;
  answer: string;
  citations: Citation[];
  confidence: number;
  timestamp: string;
  rating?: FeedbackRating;
  onRate: (answerId: string, rating: FeedbackRating) => void;
}

function AnswerBubble({ answerId, answer, citations, confidence, timestamp, rating, onRate }: AnswerProps) {
  const level = describeConfidence(confidence);
  return (
    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-start' }}>
      <div style={{
        maxWidth: '90%',
        padding: '12px 14px',
        background: '#1a1a3e',
        border: '1px solid #0f3460',
        borderRadius: '12px 12px 12px 2px',
        fontSize: '14px',
        lineHeight: 1.6,
        overflowWrap: 'anywhere',
      }}>
        <div>{answer}</div>

        {citations.length > 0 && (
          <div style={{ marginTop: '10px', fontSize: '12px', color: '#8888bb' }}>
            <div style={{ marginBottom: '4px' }}>Sources ({citations.length})</div>
            {citations.map((c, i) => (
              <details key={i} style={{ marginTop: '4px', paddingLeft: '8px', borderLeft: '2px solid #533483' }}>
                <summary style={{ cursor: 'pointer' }}>
                  {c.documentTitle}, chunk {c.chunkIndex}
                </summary>
                <blockquote style={{ marginTop: '6px', color: '#c8c8e0', whiteSpace: 'pre-wrap' }}>
                  {c.excerpt}
                </blockquote>
              </details>
            ))}
          </div>
        )}

        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: '8px', marginTop: '10px', flexWrap: 'wrap' }}>
          <span
            data-confidence={level.level}
            title="How well the answer is supported by the documents"
            style={{ fontSize: '11px', color: level.color, display: 'inline-flex', alignItems: 'center', gap: '6px' }}
          >
            <span style={{ width: '8px', height: '8px', borderRadius: '50%', background: level.color, display: 'inline-block' }} />
            Confidence: {level.label} ({(confidence * 100).toFixed(0)}%)
          </span>
          <AnswerFeedback answerId={answerId} rating={rating} onRate={onRate} />
        </div>
      </div>
      <div style={{ fontSize: '10px', color: '#666', marginTop: '3px', paddingLeft: '4px' }}>{formatTime(timestamp)}</div>
    </div>
  );
}

function formatTime(iso: string): string {
  const date = new Date(iso);
  return Number.isNaN(date.getTime()) ? '' : date.toLocaleString();
}
