import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { describeConfidence } from '../src/shared/confidence';
import { createApp, createTestDir, removeTestDir, TestApp } from './helpers';

describe('confidence indicator', () => {
  it('maps scores to high, medium and low with green, yellow and red', () => {
    expect(describeConfidence(0.85)).toMatchObject({ level: 'high', label: 'High', color: '#5cb85c' });
    expect(describeConfidence(0.7)).toMatchObject({ level: 'high' });
    expect(describeConfidence(0.5)).toMatchObject({ level: 'medium', label: 'Medium', color: '#f0ad4e' });
    expect(describeConfidence(0.4)).toMatchObject({ level: 'medium' });
    expect(describeConfidence(0.3)).toMatchObject({ level: 'low', label: 'Low', color: '#d9534f' });
    expect(describeConfidence(0)).toMatchObject({ level: 'low' });
  });
});

describe('conversation history data', () => {
  let dir: string;
  let importDir: string;
  let app: TestApp;

  beforeEach(() => {
    dir = createTestDir();
    importDir = fs.mkdtempSync(path.join(os.tmpdir(), 'kb-conv-src-'));
    app = createApp(dir);
  });

  afterEach(() => {
    removeTestDir(dir);
    removeTestDir(importDir);
  });

  it('keeps every exchange in order, with its question, citations, confidence and timestamp', async () => {
    const file = path.join(importDir, 'design.md');
    fs.writeFileSync(file, 'The architecture has three layers.\n\nRetrieval matches keywords against chunks.');
    const doc = app.documents.importDocument(file);
    await app.indexing.startIndexing(doc.id);

    await app.qa.ask('What is the architecture?');
    await app.qa.ask('How does retrieval work?');
    const history = createApp(dir).qa.getHistory();

    expect(history.map(h => h.question)).toEqual(['What is the architecture?', 'How does retrieval work?']);
    const [first] = history;
    expect(first.response.citations.length).toBeGreaterThan(0);
    expect(first.response.citations[0]).toMatchObject({
      documentId: doc.id,
      documentTitle: 'design',
    });
    expect(first.response.citations[0].excerpt.length).toBeGreaterThan(0);
    expect(first.response.confidence).toBe(0.85);
    expect(Number.isNaN(Date.parse(first.response.timestamp))).toBe(false);
  });

  it('answers without citations get the low-confidence score', async () => {
    await app.qa.ask('a question with nothing indexed');
    const [only] = app.qa.getHistory();
    expect(only.response.citations).toEqual([]);
    expect(describeConfidence(only.response.confidence).level).toBe('low');
  });
});
